sys_ws_operation.operation_script:
(function process(request, response) {
  var SCHED_TABLE = "x_2056099_indust_0_prod_sched";
  var body = {};
  try { body = JSON.parse(request.body.dataString); } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }
  var schedId = body.schedule_id;
  if (!schedId) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "schedule_id is required" } });
    return;
  }
  var gr = new GlideRecord(SCHED_TABLE);
  if (!gr.get(schedId)) {
    response.setStatus(404);
    response.setBody({ result: { success: false, error: "Production Schedule not found" } });
    return;
  }
  var currentStatus = gr.getValue("status");
  if (currentStatus == "scheduled") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Schedule is already in Scheduled status" } });
    return;
  }
  if (currentStatus == "confirmed") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Schedule is already confirmed" } });
    return;
  }
  if (currentStatus == "in_progress") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Schedule is already in progress" } });
    return;
  }
  if (currentStatus == "completed") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Cannot confirm a completed schedule" } });
    return;
  }
  if (currentStatus == "cancelled") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Cannot confirm a cancelled schedule" } });
    return;
  }
  if (currentStatus != "draft") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Only draft schedules can be confirmed. Current status: " + gr.getDisplayValue("status") } });
    return;
  }
  gr.setValue("status", "scheduled");
  gr.update();
  response.setBody({
    result: {
      success: true,
      message: "Schedule confirmed. Status changed from Draft to Scheduled.",
      record: {
        sys_id: gr.getValue("sys_id"),
        number: gr.getValue("number") || gr.getValue("sys_id"),
        status: gr.getValue("status"),
        statusDisplay: gr.getDisplayValue("status"),
        production_order: gr.getDisplayValue("production_order"),
        production_resource: gr.getDisplayValue("production_resource")
      }
    }
  });
})(request, response);
